{
  "notes": [
    {
      "title": "SBF arrest and extradition",
      "summary": "SBF arrested in Bahamas Dec 2022, extradited to U.S., released on $250M bail, house arrest in Palo Alto revoked Aug after diary leak accusation."
    },
    {
      "title": "FTX internal controls testimony",
      "summary": "Ray testified House Financial Services hearing FTX had virtually no internal controls or separateness, did not trust single piece of paper; U.S. Attorney Damian Williams called crimes biggest financial fraud in American history."
    },
    {
      "title": "Guilty pleas and civil penalties",
      "summary": "Gary Wang and Caroline Ellison pleaded guilty Dec 2022 to federal charges, face civil penalties from SEC and CFTC, plan to cooperate as witnesses."
    },
    {
      "title": "SBF charges and potential sentence",
      "summary": "SBF pleaded not guilty Jan to wire fraud, conspiracy to commit money laundering, conspiracy to misuse customer funds, faces up to 115 years jail if convicted on all charges."
    },
    {
      "title": "Industry collapse aftermath",
      "summary": "FTX collapse first of many, BlockFi filed Chapter 11 Nov 2022, Genesis Global Trading filed Chapter 11 Jan."
    },
    {
      "title": "SBF defense representation",
      "summary": "SBF represented by Cohen & Gresser, lead attorney Mark Cohen former federal prosecutor who represented Ghislaine Maxwell in Jeffrey Epstein trial, requested early release denied."
    }
  ]
}
